package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
public class AndroidEntryDiagnosticReaderTest {
 private static final String N="0123456789abcdef0123456789abcdef";
 private String source()throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/AndroidEntryDiagnosticReader.java"));}
 private AndroidEntryDiagnosticReader.Request request(){return new AndroidEntryDiagnosticReader.Request(N,8,1440,2560,0,10123,10124,10125,60);}
 @Test public void requestRequiresExactBoundedIdentity(){assertTrue(request().valid());assertFalse(new AndroidEntryDiagnosticReader.Request(N,0,1440,2560,0,10123,10124,10125,60).valid());assertFalse(new AndroidEntryDiagnosticReader.Request(N,8,1440,2560,0,10123,10124,10125,8).valid());assertFalse(new AndroidEntryDiagnosticReader.Request(N,8,0,2560,0,10123,10124,10125,60).valid());assertFalse(new AndroidEntryDiagnosticReader.Request("bad",8,1440,2560,0,10123,10124,10125,60).valid());}
 @Test public void fixedArgvHasOnlyOwnApkAndTenBoundFields(){String[] a=AndroidEntryDiagnosticReader.command(request(),"/data/app/x/base.apk",12345);assertArrayEquals(new String[]{"/system/bin/app_process","-cp","/data/app/x/base.apk","/system/bin","com.aliothmoon.maafw.once.NativeEntryDiagnosticHelper",N,"12345","8","1440","2560","0","10123","10124","10125","60"},a);}
 @Test public void finalDispatchRejectsExpiredOrRevoked(){assertTrue(AndroidEntryDiagnosticReader.dispatchAllowed(100,101,true,false,true,true));assertFalse(AndroidEntryDiagnosticReader.dispatchAllowed(101,101,true,false,true,true));assertFalse(AndroidEntryDiagnosticReader.dispatchAllowed(100,101,false,false,true,true));assertFalse(AndroidEntryDiagnosticReader.dispatchAllowed(100,101,true,true,true,true));assertFalse(AndroidEntryDiagnosticReader.dispatchAllowed(100,101,true,false,false,true));assertFalse(AndroidEntryDiagnosticReader.dispatchAllowed(100,101,true,false,true,false));}
 @Test public void frameIsOneBoundedAsciiLine(){byte[] a="EDP1|abc|0\n".getBytes(StandardCharsets.US_ASCII);assertTrue(AndroidEntryDiagnosticReader.validFrame(a,a.length));for(String bad:new String[]{"EDP1|abc|0","EDP1|abc\nEXTRA\n","EDP1|原文\n","EDP1| x\n"}){byte[] b=bad.getBytes(StandardCharsets.UTF_8);assertFalse(AndroidEntryDiagnosticReader.validFrame(b,b.length));}assertFalse(AndroidEntryDiagnosticReader.validFrame(new byte[8193],8193));}
 @Test public void noInputOrNavigationChannelExists()throws Exception{String s=source();for(String bad:new String[]{"AutoCloseOutputStream",".write(","allowAndBurnNavigation","performAction","ACTION_CLICK","COMMIT","getWindows(","/system/bin/sh","/system/bin/env","CLASSPATH="})assertFalse(bad,s.contains(bad));assertTrue(s.contains("if (stdin != null) { stdin.close(); stdin = null; }"));assertTrue(s.contains("service.newProcess(command, null, null)"));assertEquals(s.indexOf("service.newProcess("),s.lastIndexOf("service.newProcess("));}
 @Test public void gateThenBinderThenLocalDeadlineThenDispatch()throws Exception{String s=source();int gate=s.indexOf("finalGate.allowDispatch()");int binder=s.indexOf("binder == Shizuku.getBinder()",gate);int current=s.indexOf("current.getAsBoolean()",binder);int dispatch=s.indexOf("dispatchAllowed(dispatched",current);int process=s.indexOf("service.newProcess(",dispatch);assertTrue(gate>0&&binder>gate&&current>binder&&dispatch>current&&process>dispatch);}
 @Test public void quarantineRequiresHelperAndProcessCleanup()throws Exception{String s=source();assertTrue(s.contains("report == null"));assertTrue(s.contains("report.cleanup() == NativeEntryDiagnosticProtocol.Cleanup.UNKNOWN"));assertTrue(s.contains("!quiet || !descriptorsClosed"));assertTrue(s.contains("CLAIMED.compareAndSet(false, true)"));assertTrue(s.contains("knownClean() && Looper.myLooper()"));assertTrue(s.contains("if (!clean) { status = FixedStatus.CLEANUP_UNKNOWN; report = null; }"));}
 @Test public void eachFdCloseIndependentAndBytesWiped()throws Exception{String s=source();for(String x:new String[]{"input.close()","stdout.close()","stdin.close()","stderr.close()","Arrays.fill(bytes, (byte) 0)","process.destroy()"})assertTrue(x,s.contains(x));assertFalse(s.contains("printStackTrace"));assertFalse(s.contains("System.out"));assertFalse(s.contains("Log."));}
 @Test public void apkAndProcessAuthorityRetained()throws Exception{String s=source();for(String x:new String[]{"verifiedApk(context)","getPackageArchiveInfo","sameSignatures(own.signatures, archive.signatures)","canonical.equals(file.getAbsolutePath())","canonical.startsWith(\"/data/app/\")","Shizuku.getUid()==0","Application.getProcessName()","PackageManager.PERMISSION_GRANTED"})assertTrue(x,s.contains(x));}
 @Test public void phaseCannotRenew(){assertEquals(15000,AndroidEntryDiagnosticReader.PHASE_MILLIS);}
}
